// 2. Parse response
const responseData = pm.response.json();

pm.test("Cart created and ID saved", function () {
    // DummyJSON returns simulated ID (e.g. 209), but database only holds IDs 1-20.
    // We set '1' to allow real GET and DELETE calls downstream to succeed.
    const realCartId = 1; 

    pm.environment.set("chainedCartId", realCartId);
    pm.environment.set("expectedTotalProducts", responseData.totalProducts);

    console.log(`[DAY 3 STEP 1] Simulated creation ID: ${responseData.id} | Using valid DB Cart ID: ${realCartId}`);
});

// 1. Check HTTP Status
pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Validate Cart Content and Control Workflow Execution
pm.test("Cart details match created payload", function () {
    const responseData = pm.response.json();
    const expectedTotal = pm.environment.get("expectedTotalProducts");

    pm.expect(responseData.totalProducts).to.be.a("number").that.is.above(0);

    // WORKFLOW CONTROL (postman.setNextRequest)
    // If the cart has products, jump directly to Step 3 (Delete Cart).
    // If empty, terminate the collection run immediately.
    if (responseData.products && responseData.products.length > 0) {
        console.log("[WORKFLOW] Cart contains products. Proceeding to Delete Cart.");
        // postman.setNextRequest("Request_3_Name"); // Used during Collection Runner execution
    } else {
        console.log("[WORKFLOW] Cart is empty. Stopping execution.");
        postman.setNextRequest(null); // Halts collection runner loop
    }
});

// 1. Verify deletion HTTP status
pm.test("Status code is 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Verify soft-delete payload response
pm.test("Cart marked as deleted", function () {
    const responseData = pm.response.json();

    pm.expect(responseData.isDeleted).to.be.true;
    console.log(`[DAY 3 STEP 3] Cart ${responseData.id} deleted successfully.`);
});
